import ghidra.app.script.GhidraScript;
import ghidra.program.model.data.*;
import ghidra.program.model.symbol.*;
import ghidra.program.model.listing.*;
import java.nio.file.*;
public class N3DDefineFarTable extends GhidraScript {
 public void run() throws Exception {
  StructureDataType dt=new StructureDataType("NE_FARPTR16_PROVEN",0);
  dt.add(WordDataType.dataType,"offset","16-bit code offset");
  dt.add(WordDataType.dataType,"selector","Loader-relocated NE segment selector");
  var type=currentProgram.getDataTypeManager().addDataType(dt,DataTypeConflictHandler.DEFAULT_HANDLER);
  int count=0;
  for(String row:Files.readAllLines(Paths.get(getScriptArgs()[0])).subList(1,866)) {
   String[] cols=row.split("\t");var a=toAddr(cols[0]);var target=toAddr(cols[1]);
   int expectedOffset=Integer.parseInt(cols[1].split(":")[1],16);
   int expectedSelector=Integer.parseInt(cols[1].split(":")[0],16);
   if((getShort(a)&0xffff)!=expectedOffset || (getShort(a.add(2))&0xffff)!=expectedSelector)
    throw new Exception("Loaded pointer differs from raw relocation evidence at "+a);
   if(getDataAt(a)==null || !getDataAt(a).isDefined())createData(a,type);
   currentProgram.getReferenceManager().addMemoryReference(a,target,RefType.DATA,SourceType.USER_DEFINED,0);
   currentProgram.getListing().setComment(a,CodeUnit.EOL_COMMENT,"Confirmed NE seg4 relocation chain record "+cols[3]+"; far code target "+target+"; runtime/class ownership unverified.");
   count++;
  }
  println("PROVEN_FAR_POINTER_ENTRIES "+count);
 }
}

