import ghidra.app.script.GhidraScript;
import java.io.*;
import java.nio.file.*;
import java.util.*;
public class N3DInspectClassMetadata extends GhidraScript {
 public void run() throws Exception {
  try(PrintWriter p=new PrintWriter(getScriptArgs()[0])){
   p.println("metadata\tloaded_words\tfar_string_address\tfar_string");
   List<Integer> offsets=new ArrayList<>();
   if(getScriptArgs().length>1){for(String line:Files.readAllLines(Paths.get(getScriptArgs()[1])))offsets.add(Integer.parseInt(line,16));}
   else for(int o:new int[]{0x4ee,0x500,0x514,0x524,0x534,0x544,0x554,0x564,0x574,0x58c,0x594,0x5a4,0x676,0x686,0x696,0x784,0x794,0x7a4,0x80a})offsets.add(o);
   for(int o:offsets){
    var a=toAddr(String.format("1048:%04x",o));StringBuilder words=new StringBuilder();for(int i=0;i<10;i++)words.append(String.format("%04x ",getShort(a.add(i*2))&0xffff));
    String ptr=String.format("%04x:%04x",getShort(a.add(2))&0xffff,getShort(a)&0xffff);StringBuilder str=new StringBuilder();
    try{var s=toAddr(ptr);for(int i=0;i<100;i++){int c=getByte(s.add(i))&255;if(c==0)break;if(c<32||c>126){str.append("[non-ascii]");break;}str.append((char)c);}}catch(Exception e){str.append("[unmapped]");}
    p.println(a+"\t"+words+"\t"+ptr+"\t"+str);
   }
  }
 }
}

