import ghidra.app.script.GhidraScript;
import ghidra.program.model.symbol.SourceType;
import java.nio.file.*;
public class N3DApplyEvidenceAnnotations extends GhidraScript {
 public void run() throws Exception {
  int n=0;
  var lines=Files.readAllLines(Paths.get(getScriptArgs()[0]));
  for(String line:lines.subList(1,lines.size())){
   String[] c=line.split("\t",3);var f=getFunctionAt(toAddr(c[0]));if(f==null)throw new Exception("Missing function "+c[0]);
   f.setName(c[1],SourceType.USER_DEFINED);f.setComment(c[2]+"\nStatic evidence pass 2, 2026-10-28; original EXE SHA256 12fe5168783446275802e0e947898261b5eca6b88288f3a895fc1faa4c544481.");n++;
  }
  println("BOUNDED_FUNCTION_ANNOTATIONS "+n);
 }
}
